SEP = "|"
QUOTE = "'"


def _split(text):
    """Split text on SEP outside quotes, returning raw (key, value, quoted) triples."""
    fields = []
    i, n = 0, len(text)
    while i <= n:
        # read key up to '=' or SEP or end
        start = i
        while i < n and text[i] not in (SEP, "="):
            i += 1
        key = text[start:i]
        if i >= n or text[i] == SEP:
            if key.strip():
                raise ValueError(f"field without '=': {key!r}")
            i += 1
            if i > n:
                break
            continue
        i += 1  # skip '='
        # read value
        j = i
        while j < n and text[j].isspace():
            j += 1
        if j < n and text[j] == QUOTE:
            j += 1
            value = ""
            closed = False
            while j < n:
                if text[j] == QUOTE:
                    if j + 1 < n and text[j + 1] == QUOTE:
                        value += QUOTE
                        j += 2
                        continue
                    closed = True
                    j += 1
                    break
                value += text[j]
                j += 1
            if not closed:
                raise ValueError(f"unclosed quote in {text!r}")
            while j < n and text[j].isspace():
                j += 1
            if j < n and text[j] != SEP:
                raise ValueError(f"junk after quoted value in {text!r}")
            fields.append((key, value))
            i = j + 1
        else:
            while j < n and text[j] != SEP:
                j += 1
            fields.append((key, text[i:j].strip()))
            i = j + 1
        if i > n:
            break
    return fields


def parse_fields(text):
    """Parse a line like name=Ann| note='hi| there' into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    for key, value in _split(text):
        key = key.strip()
        if not key:
            raise ValueError(f"empty key in {text!r}")
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = value
    return result
